// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// 1D layouts for vectors (all use dimension 'i')
	DEFINE_PROTO_STRUCT(x_layout, i_vec);

	// 2D layout for matrix A: dimensions 'i' (rows) and 'j' (columns), row-major:
	// scalar ^ j_vec ^ i_vec  =>  outer 'i', inner 'j'
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	auto n = x1 | get_length<'i'>();

	// Initialize the four vectors
	traverser(x1, x2, y_1, y_2).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x1[state] = (num_t)((i % n)) / n;
		x2[state] = (num_t)(((i + 1) % n)) / n;
		y_1[state] = (num_t)(((i + 3) % n)) / n;
		y_2[state] = (num_t)(((i + 4) % n)) / n;
	});

	// Initialize matrix A: A[i][j] = (i * j % n) / n
	auto nA = A | get_length<'i'>();

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = (num_t)((i * j) % nA) / nA;
	});
}

// computation kernel
//
// Original mathematical computation:
//
//   // First part:
//   for i in 0..N-1:
//     for j in 0..N-1:
//       x1[i] += A[i][j] * y_1[j];
//
//   // Second part:
//   for i in 0..N-1:
//     for j in 0..N-1:
//       x2[i] += A[j][i] * y_2[j];
//
// Optimized version below keeps the same semantics but:
//   - Tiles both i and j to improve cache locality.
//   - For the first part, keeps x1[i] in a register while reducing over j.
//   - For the second part, traverses A^T by rows (j outer, i inner) using a
//     renamed view of A, reusing y_2[j] inside the inner loop.
//   - Uses only Noarr traversers/for_dims to express iteration.
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;
	using noarr::lit;

	// Views of y_1 and y_2 as vectors over 'j' (needed for y_[*][j])
	auto y_1_j = y_1.get_ref() ^ rename<'i', 'j'>();
	auto y_2_j = y_2.get_ref() ^ rename<'i', 'j'>();

	// Transposed *view* of A to access A[j][i] while keeping the same
	// underlying row-major layout:
	//   - Original A dims: 'i' (rows), 'j' (cols)
	//   - After rename<'i','j','j','i'>: dims become 'j' (old 'i'), 'i' (old 'j')
	//   - A_t[j, i] == A[j][i]
	auto A_t = A.get_ref() ^ rename<'i', 'j', 'j', 'i'>();

	// Tunable tile sizes; chosen as reasonable defaults for modern CPUs.
	constexpr std::size_t tile_i = 64;
	constexpr std::size_t tile_j = 64;

	// Proto-structures for dynamic blocking of i and j. The extra guard
	// dimensions 'r' and 's' ensure that the last, possibly partial, tiles
	// are handled correctly without reading/writing outside [0, N).
	auto tile_i_blocks = into_blocks_dynamic<'i', 'I', 'i', 'r'>(lit<tile_i>);
	auto tile_j_blocks = into_blocks_dynamic<'j', 'J', 'j', 's'>(lit<tile_j>);

#pragma scop
	// --------------------------------------------------------------------
	// Part 1: x1[i] += sum_j A[i, j] * y_1[j]
	//
	// We:
	//   - Block i into tiles 'I' and in-tile index 'i' (with guard 'r'),
	//   - Block j into tiles 'J' and in-tile index 'j' (with guard 's'),
	//   - For each i, keep a scalar accumulator 'acc' in a register and
	//     only write x1[i] once after summing over all j.
	// --------------------------------------------------------------------
	traverser(x1, y_1_j, A)
		.order(tile_i_blocks ^ tile_j_blocks)
		.template for_dims<'I'>([=](auto trav_I) {
			// trav_I: 'I' fixed, remaining dims: i, r, J, j, s

			// Loop over all valid i indices inside this I-tile.
			trav_I.template for_dims<'i', 'r'>([=](auto trav_i) {
				// trav_i: 'I', 'i', 'r' fixed; J, j, s still varying
				auto s_i = trav_i.state(); // contains at least the current 'i'

				// Keep x1[i] in a register while reducing over j.
				num_t acc = x1[s_i];

				// Sweep over all column tiles J and j within each tile.
				trav_i.template for_dims<'J'>([=, &acc](auto trav_J) {
					// trav_J: also has 'J' fixed; j, s still varying
					trav_J.template for_dims<'j', 's'>([=, &acc](auto trav_ij) {
						// trav_ij: all dims fixed (I, i, r, J, j, s)
						// Only combinations with valid guard 's' are visited.
						acc += A[trav_ij] * y_1_j[trav_ij];
					});
				});

				// Single write-back per i.
				x1[s_i] = acc;
			});
		});

	// --------------------------------------------------------------------
	// Part 2: x2[i] += sum_j A[j, i] * y_2[j]
	//
	// We use the transposed view A_t[j, i] == A[j, i] and traverse it
	// in a cache-friendly order:
	//   - Block j into (J, j, s) and i into (I, i, r),
	//   - Outer loops over J then j (source rows of A / A_t),
	//   - Inner loops over I then i (contiguous in the row of A_t),
	//   - y_2[j] is loaded once per j and reused across all i.
	//
	// This corresponds to:
	//   for j:
	//     tmp = y_2[j];
	//     for i:
	//       x2[i] += A[j, i] * tmp;
	// but with blocking on both i and j.
	// --------------------------------------------------------------------
	traverser(x2, y_2_j, A_t)
		.order(tile_j_blocks ^ tile_i_blocks) // first split j, then i
		.template for_dims<'J'>([=](auto trav_J) {
			// trav_J: 'J' fixed, remaining dims: j, s, I, i, r

			// Iterate all valid j in this J-tile.
			trav_J.template for_dims<'j', 's'>([=](auto trav_j) {
				// trav_j: 'J', 'j', 's' fixed; I, i, r still varying
				auto s_j = trav_j.state(); // contains at least current 'j'

				// Reuse y_2[j] for all i in this j.
				num_t y_val = y_2_j[s_j];

				// Sweep all tiles of i and i-indices inside each tile.
				trav_j.template for_dims<'I'>([=, y_val](auto trav_I) {
					trav_I.template for_dims<'i', 'r'>([=, y_val](auto trav_ij) {
						// trav_ij: all dims fixed (J, j, s, I, i, r)
						x2[trav_ij] = x2[trav_ij] + A_t[trav_ij] * y_val;
					});
				});
			});
		});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

